#Program 0
Constraints:
Numbers will be in the range of int and int64

python
```python
def f(inputs: List[str]):
    def transform(number: str) -> int:
        if number in [input for input in inputs]:
            raise Exception("Duplicate Number found.")
        return int(number)
    return transform
```
3yo
```cpp
class Solution:
    def f(self, inputs: List[str]) -> List[str]:
        seen = {}
        output = []
        for num in inputs:
            if num in seen:
                raise Exception("Duplicate Number found.")
            seen[num] = True
            output.append(str(int(num)))
        return output
```
16yo
```go
import (
	"strconv"
	"strings"
)

func f(inputs []string) []string {
	seen := make(map[string]bool)
	output := make([]string, len(inputs))
	for i, num := range inputs {
		_, exists := seen[num]
		if exists {
			panic("Duplicate Number found.")
		}
		seen[num] = true
		output[i] = strconv.Itoa(Int(num))
	}
	return output
}
```
