```cpp
class Solution:
    def f(self, inputs: List[str]) -> List[str]:
        seen = {}
        output = []
        for num in inputs:
            if num in seen:
                raise Exception("Duplicate Number found.")
            seen[num] = True
            output.append(str(int(num)))
        return output
