import (
	"strconv"
	"strings"
)

func f(inputs []string) []string {
	seen := make(map[string]bool)
	output := make([]string, len(inputs))
	for i, num := range inputs {
		_, exists := seen[num]
		if exists {
			panic("Duplicate Number found.")
		}
		seen[num] = true
		output[i] = strconv.Itoa(Int(num))
	}
	return output
}
